def transform(grid):
    rows, cols = len(grid), len(grid[0])
    counts = {v: sum(cell == v for row in grid for cell in row) for row in grid for v in row}
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and counts[row[0]] == cols:
            return [[3 if value == 0 else 4 for value in out_row] for out_row in grid[r + 1:]]
    for c in range(cols):
        value = grid[0][c]
        if all(row[c] == value for row in grid) and counts[value] == rows:
            return [[3 if value == 4 else 4 for value in row[c + 1:]] for row in grid]
    raise ValueError('separator not found')
